import type { PinningProvider, PinResult, PinStatus } from './types';

/** Fixed upload URL for Pinata file uploads (always this domain, not configurable) */
const UPLOAD_URL = 'https://uploads.pinata.cloud';

/** Timeout for all Pinata API requests — higher ceiling for external network uploads */
const REQUEST_TIMEOUT_MS = 30_000;

/**
 * PinningProvider implementation for Pinata's native v3 API.
 *
 * Pinata deprecated their PSA endpoint (/psa returns 404). Their current API
 * uses proprietary endpoints:
 * - /v3/files for upload and management
 * - /pinning/pinByHash for CID-based pinning
 *
 * Two base URLs are used:
 * - https://uploads.pinata.cloud -- file uploads (fixed, not configurable)
 * - https://api.pinata.cloud -- management operations (list, delete, pinByHash)
 *
 * The `endpoint` constructor param should be the management URL
 * (https://api.pinata.cloud).
 */
export class PinataProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken: string;
  private readonly gatewayUrl?: string;

  constructor(endpoint: string, authToken: string, gatewayUrl?: string) {
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
    this.gatewayUrl = gatewayUrl?.replace(/\/+$/, '');
  }

  /**
   * Upload and pin data via Pinata's v3 file upload API.
   * POST https://uploads.pinata.cloud/v3/files
   */
  async pin(data: Uint8Array, name?: string): Promise<PinResult> {
    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
    const formData = new FormData();
    formData.append('file', blob, name ?? `cipherbox-${Date.now()}`);

    const response = await fetch(`${UPLOAD_URL}/v3/files`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${this.authToken}` },
      body: formData,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Pinata upload failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as {
      data: { id: string; cid: string; size: number };
    };
    return { cid: result.data.cid, size: result.data.size };
  }

  /**
   * Pin an existing CID via Pinata's pinByHash endpoint.
   * Pinata will retrieve the content from the IPFS network and pin it.
   * POST https://api.pinata.cloud/pinning/pinByHash
   */
  async pinByCid(cid: string): Promise<{ cid: string; status: string }> {
    const response = await fetch(`${this.endpoint}/pinning/pinByHash`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.authToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ hashToPin: cid }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Pinata pinByHash failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as { ipfsHash: string; status: string };
    return { cid: result.ipfsHash, status: result.status };
  }

  /**
   * Remove a pin by CID.
   * Pinata uses file IDs for deletion, so we first look up the file(s)
   * by CID, then delete each one.
   */
  async unpin(cid: string): Promise<void> {
    const listResponse = await fetch(`${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${this.authToken}` },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!listResponse.ok) {
      throw new Error(`Pinata list failed: ${listResponse.status}`);
    }

    const listResult = (await listResponse.json()) as {
      data: { files: Array<{ id: string }> };
    };

    for (const file of listResult.data.files) {
      const deleteResponse = await fetch(`${this.endpoint}/v3/files/${file.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${this.authToken}` },
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (!deleteResponse.ok) {
        throw new Error(`Pinata delete failed: ${deleteResponse.status}`);
      }
    }
  }

  /**
   * Check pin status by CID.
   * Queries the Pinata v3 files API and returns 'pinned' if found, 'failed' if not.
   */
  async status(cid: string): Promise<PinStatus> {
    const response = await fetch(`${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${this.authToken}` },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) return { cid, status: 'failed' };

    const result = (await response.json()) as {
      data: { files: Array<{ id: string; cid: string }> };
    };

    return {
      cid,
      status: result.data.files.length > 0 ? 'pinned' : 'failed',
    };
  }

  /**
   * Fetch pinned content by CID via Pinata's gateway.
   * Uses the dedicated gateway URL if configured, otherwise the default public gateway.
   */
  async get(cid: string): Promise<Uint8Array> {
    const gateway = this.gatewayUrl ?? 'https://gateway.pinata.cloud';
    const response = await fetch(`${gateway}/ipfs/${encodeURIComponent(cid)}`, {
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      throw new Error(`Pinata gateway fetch failed: ${response.status}`);
    }

    return new Uint8Array(await response.arrayBuffer());
  }
}

import { ApiProperty } from '@nestjs/swagger';
import {
  IsString,
  IsNotEmpty,
  IsOptional,
  IsNumber,
  IsBase64,
  IsArray,
  IsIn,
  ArrayMaxSize,
  ArrayMinSize,
  ValidateNested,
  Matches,
  MaxLength,
  MinLength,
} from 'class-validator';
import { Type } from 'class-transformer';

export class PublishIpnsDto {
  @ApiProperty({
    description: 'IPNS name (k51... CIDv1 format)',
    example: 'REDACTED',
  })
  @IsString()
  @IsNotEmpty()
  // [SECURITY: MEDIUM-12] IPNS name validation - accept k51 (base36) or bafzaa (base32) CIDv1 libp2p-key
  // Both formats are accepted for forward compatibility and external tool support.
  // Client code generates base36 (k51...) format, but we accept base32 (bafzaa...) for interoperability.
  @Matches(/^(k51qzi5uqu5[a-z0-9]{40,60}|bafzaa[a-z2-7]{50,70})$/, {
    message: 'ipnsName must be a valid CIDv1 libp2p-key (k51qzi5uqu5... or bafzaa...)',
  })
  @MaxLength(70)
  ipnsName!: string;

  @ApiProperty({
    description: 'Base64-encoded marshaled IPNS record',
    example: 'CiQBqKAFp...',
  })
  @IsString()
  @IsNotEmpty()
  @IsBase64()
  @MaxLength(10000) // IPNS records should be small
  record!: string;

  @ApiProperty({
    description: 'CID of the encrypted metadata this record points to',
    example: 'REDACTED',
  })
  @IsString()
  @IsNotEmpty()
  // [SECURITY: MEDIUM-10] Validate CID format - must start with bafy/bafk (CIDv1) or Qm (CIDv0)
  @Matches(/^(bafy|bafk|Qm)[a-zA-Z0-9]+$/, {
    message: 'metadataCid must be a valid CID (bafy..., bafk..., or Qm...)',
  })
  @MaxLength(100)
  metadataCid!: string;

  @ApiProperty({
    description:
      'Hex-encoded ECIES-wrapped Ed25519 private key for TEE republishing (required on first publish)',
    required: false,
    example: '04abcd1234...',
  })
  @IsString()
  @IsOptional()
  // [SECURITY: MEDIUM-09] Validate hex format and reasonable length for ECIES ciphertext
  @Matches(/^[0-9a-fA-F]+$/, {
    message: 'encryptedIpnsPrivateKey must be hex-encoded',
  })
  @MinLength(100, {
    message: 'encryptedIpnsPrivateKey too short for ECIES ciphertext',
  })
  @MaxLength(1000, {
    message: 'encryptedIpnsPrivateKey too long',
  })
  encryptedIpnsPrivateKey?: string;

  @ApiProperty({
    description: 'TEE key epoch (required with encryptedIpnsPrivateKey)',
    required: false,
    example: 1,
  })
  @IsNumber()
  @IsOptional()
  keyEpoch?: number;

  @ApiProperty({
    description:
      'Expected sequence number for conflict detection. When present, the API validates against the stored value and rejects with 409 if mismatched. Omit for backward-compatible unconditional publish.',
    required: false,
    example: '5',
  })
  @IsOptional()
  @IsString()
  @Matches(/^\d+$/, { message: 'expectedSequenceNumber must be a numeric string' })
  expectedSequenceNumber?: string;
}

export class PublishIpnsResponseDto {
  @ApiProperty({
    description: 'Whether the publish operation succeeded',
    example: true,
  })
  success!: boolean;

  @ApiProperty({
    description: 'IPNS name that was published',
    example: 'REDACTED',
  })
  ipnsName!: string;

  @ApiProperty({
    description: 'Current sequence number (bigint as string)',
    example: '1',
  })
  sequenceNumber!: string;
}

/**
 * Single entry within a batch publish request.
 * Same fields as PublishIpnsDto plus optional recordType.
 */
export class PublishIpnsEntryDto {
  @ApiProperty({
    description: 'IPNS name (k51... CIDv1 format)',
    example: 'REDACTED',
  })
  @IsString()
  @IsNotEmpty()
  @Matches(/^(k51qzi5uqu5[a-z0-9]{40,60}|bafzaa[a-z2-7]{50,70})$/, {
    message: 'ipnsName must be a valid CIDv1 libp2p-key (k51qzi5uqu5... or bafzaa...)',
  })
  @MaxLength(70)
  ipnsName!: string;

  @ApiProperty({
    description: 'Base64-encoded marshaled IPNS record',
    example: 'CiQBqKAFp...',
  })
  @IsString()
  @IsNotEmpty()
  @IsBase64()
  @MaxLength(10000)
  record!: string;

  @ApiProperty({
    description: 'CID of the encrypted metadata this record points to',
    example: 'REDACTED',
  })
  @IsString()
  @IsNotEmpty()
  @Matches(/^(bafy|bafk|Qm)[a-zA-Z0-9]+$/, {
    message: 'metadataCid must be a valid CID (bafy..., bafk..., or Qm...)',
  })
  @MaxLength(100)
  metadataCid!: string;

  @ApiProperty({
    description: 'Hex-encoded ECIES-wrapped Ed25519 private key for TEE republishing',
    required: false,
    example: '04abcd1234...',
  })
  @IsString()
  @IsOptional()
  @Matches(/^[0-9a-fA-F]+$/, {
    message: 'encryptedIpnsPrivateKey must be hex-encoded',
  })
  @MinLength(100, {
    message: 'encryptedIpnsPrivateKey too short for ECIES ciphertext',
  })
  @MaxLength(1000, {
    message: 'encryptedIpnsPrivateKey too long',
  })
  encryptedIpnsPrivateKey?: string;

  @ApiProperty({
    description: 'TEE key epoch (required with encryptedIpnsPrivateKey)',
    required: false,
    example: 1,
  })
  @IsNumber()
  @IsOptional()
  keyEpoch?: number;

  @ApiProperty({
    description: "Record type: 'folder' for folder metadata, 'file' for per-file metadata",
    required: false,
    enum: ['folder', 'file'],
    default: 'folder',
    example: 'file',
  })
  @IsString()
  @IsOptional()
  @IsIn(['folder', 'file'])
  recordType?: 'folder' | 'file';

  @ApiProperty({
    description:
      'Expected sequence number for conflict detection. When present, the API validates against the stored value and rejects with 409 if mismatched. Omit for backward-compatible unconditional publish.',
    required: false,
    example: '5',
  })
  @IsOptional()
  @IsString()
  @Matches(/^\d+$/, { message: 'expectedSequenceNumber must be a numeric string' })
  expectedSequenceNumber?: string;
}

/**
 * Batch publish request: up to 200 IPNS records in a single API call.
 */
export class BatchPublishIpnsDto {
  @ApiProperty({
    description: 'Array of IPNS records to publish (max 200)',
    type: [PublishIpnsEntryDto],
  })
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => PublishIpnsEntryDto)
  @ArrayMinSize(1)
  @ArrayMaxSize(200)
  records!: PublishIpnsEntryDto[];
}

/**
 * Batch publish response with per-record results and summary counts.
 */
export class BatchPublishIpnsResponseDto {
  @ApiProperty({
    description: 'Per-record publish results',
    type: [PublishIpnsResponseDto],
  })
  results!: PublishIpnsResponseDto[];

  @ApiProperty({
    description: 'Number of records that succeeded',
    example: 5,
  })
  totalSucceeded!: number;

  @ApiProperty({
    description: 'Number of records that failed',
    example: 0,
  })
  totalFailed!: number;
}

