  @ApiProperty({
    description: 'Maximum storage limit in bytes (500 MiB)',
    example: 524288000,
  })
  limitBytes!: number;

  @ApiProperty({
    description: 'Remaining storage in bytes',
    example: 419430400,
  })
  remainingBytes!: number;

  @ApiProperty({
    description: 'Whether quota is advisory-only (BYO users manage their own storage)',
    example: false,
  })
  advisory!: boolean;
}

